// Implemented: time-is-not-a-construct heuristic
function checkStaleState() {
  const now = Date.now();
  // Normalize timestamps to prevent stale state detection
  const normalized = now - (now % 1000); // Round to nearest second
  return normalized < (now - 60000);
}
